using Clock=chrono::steady_clock;
static long long nowms(){return chrono::duration_cast<chrono::milliseconds>(Clock::now().time_since_epoch()).count();}
static string lower(string s){for(char &c:s) if(c>='A'&&c<='Z') c+=32;return s;}
static string trim(string s){size_t a=0,b=s.size();while(a<b&&(s[a]==' '||s[a]=='\t'||s[a]=='\r'||s[a]=='\n'))a++;while(b>a&&(s[b-1]==' '||s[b-1]=='\t'||s[b-1]=='\r'||s[b-1]=='\n'))b--;return s.substr(a,b-a);}
static bool number(const string&s,unsigned long long &x){if(s.empty())return false;x=0;for(unsigned char c:s){if(c<'0'||c>'9'||x>(ULLONG_MAX-(c-'0'))/10)return false;x=x*10+c-'0';}return true;}
static bool tokenchar(unsigned char c){return (c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||strchr("!#$%&'*+-.^_`|~",c);}
static bool istoken(const string&s){if(s.empty())return false;for(unsigned char c:s)if(!tokenchar(c))return false;return true;}
static bool hasToken(const string&s,const string&t){size_t p=0;while(p<=s.size()){size_t e=s.find(',',p);if(e==string::npos)e=s.size();if(lower(trim(s.substr(p,e-p)))==t)return true;if(e==s.size())break;p=e+1;}return false;}
struct Config{string listen,root,origin;long long maxconn,hbytes,htime,idle,wtime,maxreq,depth,cachebytes,ttl;};
static bool address(const string&s,sockaddr_in &a){size_t p=s.rfind(':');if(p==string::npos||p==0)return false;unsigned long long port;if(!number(s.substr(p+1),port)||port==0||port>65535)return false;string host=s.substr(0,p);memset(&a,0,sizeof(a));a.sin_family=AF_INET;a.sin_port=htons(port);if(inet_pton(AF_INET,host.c_str(),&a.sin_addr)==1)return true;addrinfo hints{},*res=nullptr;hints.ai_family=AF_INET;hints.ai_socktype=SOCK_STREAM;if(getaddrinfo(host.c_str(),nullptr,&hints,&res))return false;a.sin_addr=((sockaddr_in*)res->ai_addr)->sin_addr;freeaddrinfo(res);return true;}
static bool config(const char*file,Config&c){ifstream f(file);if(!f)return false;unordered_map<string,string> m;string s;while(getline(f,s)){s=trim(s);if(s.empty()||s[0]=='#')continue;auto p=s.find('=');if(p==string::npos)return false;string k=trim(s.substr(0,p)),v=trim(s.substr(p+1));if(k.empty()||v.empty()||m.count(k))return false;m[k]=v;}vector<string> keys={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth","origin_address","cache_bytes","cache_ttl_ms"};if(m.size()!=keys.size())return false;for(auto &k:keys)if(!m.count(k))return false;c.listen=m["listen"];c.root=m["root"];c.origin=m["origin_address"];if(c.root.empty()||c.root[0]!='/')return false;struct stat st;if(stat(c.root.c_str(),&st)||!S_ISDIR(st.st_mode))return false;auto val=[&](string k,long long &v){unsigned long long n;if(!number(m[k],n)||n==0||n>LLONG_MAX)return false;v=n;return true;};sockaddr_in a,b;return address(c.listen,a)&&address(c.origin,b)&&val("max_connections",c.maxconn)&&val("header_bytes",c.hbytes)&&val("header_timeout_ms",c.htime)&&val("idle_timeout_ms",c.idle)&&val("write_timeout_ms",c.wtime)&&val("max_requests",c.maxreq)&&val("pipeline_depth",c.depth)&&val("cache_bytes",c.cachebytes)&&val("cache_ttl_ms",c.ttl);}
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<128)continue;int n;unsigned v;if(c>=0xc2&&c<=0xdf){n=1;v=c&31;}else if(c>=0xe0&&c<=0xef){n=2;v=c&15;}else if(c>=0xf0&&c<=0xf4){n=3;v=c&7;}else return false;if(i+n>s.size())return false;for(int j=0;j<n;j++){unsigned char d=s[i++];if((d&0xc0)!=0x80)return false;v=(v<<6)|(d&63);}if((n==2&&v<0x800)||(n==3&&v<0x10000)||(v>=0xd800&&v<=0xdfff)||v>0x10ffff)return false;}return true;}
static int hex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static int pathdecode(const string&t,string &path){if(t.empty()||t[0]!='/'||t.find('#')!=string::npos)return 400;size_t q=t.find('?');string raw=t.substr(0,q);path.clear();for(size_t i=0;i<raw.size();i++){unsigned char c=raw[i];if(c=='%'){if(i+2>=raw.size()||hex(raw[i+1])<0||hex(raw[i+2])<0)return 400;c=(hex(raw[i+1])<<4)|hex(raw[i+2]);i+=2;}if(c==0||c=='\\')return 400;path+=(char)c;}if(!utf8(path))return 400;size_t p=0;while(p<=path.size()){size_t e=path.find('/',p);if(e==string::npos)e=path.size();if(path.substr(p,e-p)=="..")return 403;if(e==path.size())break;p=e+1;}return 0;}
struct Entry{shared_ptr<string> body;string extra,etag;long long expiry,ttl;list<string>::iterator lru;};
struct Client{int fd=-1,up=-1,file=-1;string in,out,upout,upin;size_t opos=0,upos=0,bpos=0;shared_ptr<string> body;off_t fpos=0;long long flen=0;int state=0; // 0 read, 1 write, 2 upstream send, 3 upstream read
 long long deadline=0,first=0,requests=0;bool close=false,head=false;string key,host,lang,target;bool gateway=false;};
class Server{Config cfg;int ep=-1,ls=-1,root=-1;sockaddr_in origin{};unordered_map<int,unique_ptr<Client>> clients;unordered_map<int,int> upstream;unordered_map<string,Entry> cache;list<string> lru;long long used=0;
 void ev(int fd,uint32_t e,int op=EPOLL_CTL_MOD){epoll_event x{};x.events=e|EPOLLRDHUP;x.data.fd=fd;epoll_ctl(ep,op,fd,&x);}
 void delup(Client&c){if(c.up>=0){epoll_ctl(ep,EPOLL_CTL_DEL,c.up,nullptr);upstream.erase(c.up);close(c.up);c.up=-1;}}
 void drop(int fd){auto it=clients.find(fd);if(it==clients.end())return;Client&c=*it->second;delup(c);if(c.file>=0)close(c.file);epoll_ctl(ep,EPOLL_CTL_DEL,fd,nullptr);close(fd);clients.erase(it);}
 string reason(int s){switch(s){case 200:return "OK";case 304:return "Not Modified";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 431:return "Request Header Fields Too Large";case 502:return "Bad Gateway";default:return "Response";}}
 void response(Client&c,int status,long long len,const string&extra="",shared_ptr<string> body=nullptr,int file=-1){delup(c);if(c.file>=0){close(c.file);c.file=-1;}c.file=file;c.fpos=0;c.flen=len;c.body=body;c.bpos=0;c.opos=0;c.out="HTTP/1.1 "+to_string(status)+" "+reason(status)+"\r\nContent-Length: "+to_string(len)+"\r\n"+extra+"Connection: "+(c.close?"close":"keep-alive")+"\r\n\r\n";c.state=1;c.deadline=nowms()+cfg.wtime;ev(c.fd,EPOLLOUT);}
 void error(Client&c,int status,bool force=false){if(force)c.close=true;response(c,status,0);}
 void touch(unordered_map<string,Entry>::iterator it){lru.splice(lru.begin(),lru,it->second.lru);it->second.lru=lru.begin();}
 void erasecache(unordered_map<string,Entry>::iterator it){used-=it->second.body->size();lru.erase(it->second.lru);cache.erase(it);}
 void store(const string&key,shared_ptr<string>b,const string&extra,const string&etag,long long ttl){auto old=cache.find(key);if(old!=cache.end())erasecache(old);if((unsigned long long)b->size()>(unsigned long long)cfg.cachebytes||ttl<=0)return;while(used+(long long)b->size()>cfg.cachebytes&&!lru.empty()){auto it=cache.find(lru.back());erasecache(it);}lru.push_front(key);Entry e{b,extra,etag,nowms()+ttl,ttl,lru.begin()};used+=b->size();cache.emplace(key,move(e));}
 bool parsefields(const string&s,vector<pair<string,string>>&fields){size_t p=0;while(p<s.size()){size_t e=s.find("\r\n",p);if(e==string::npos)return false;string line=s.substr(p,e-p);p=e+2;if(line.empty())return p==s.size();if(line[0]==' '||line[0]=='\t')return false;auto col=line.find(':');if(col==string::npos||!istoken(line.substr(0,col)))return false;string v=line.substr(col+1);for(unsigned char c:v)if(c==0||c=='\r'||c=='\n'||(c<32&&c!='\t')||c==127)return false;fields.emplace_back(lower(line.substr(0,col)),trim(v));}return true;}
 void local(Client&c,const string&path){int d=dup(root);if(d<0){error(c,404);return;}size_t p=1;vector<string> parts;while(p<=path.size()){size_t e=path.find('/',p);if(e==string::npos)e=path.size();string v=path.substr(p,e-p);if(!v.empty()&&v!=".")parts.push_back(v);if(e==path.size())break;p=e+1;}if(parts.empty()){close(d);error(c,403);return;}for(size_t i=0;i<parts.size();i++){int flags=O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK;if(i+1<parts.size())flags|=O_DIRECTORY;int n=openat(d,parts[i].c_str(),flags);if(n<0){int er=errno;struct stat st{};bool sym=fstatat(d,parts[i].c_str(),&st,AT_SYMLINK_NOFOLLOW)==0&&S_ISLNK(st.st_mode);close(d);error(c,(sym||er==ELOOP||er==EACCES)?403:404);return;}close(d);d=n;}struct stat st;if(fstat(d,&st)||!S_ISREG(st.st_mode)){close(d);error(c,403);return;}if(path.back()=='/'){close(d);error(c,403);return;}response(c,200,st.st_size,"Content-Type: application/octet-stream\r\n",nullptr,d);}
 void gateway(Client&c){auto it=cache.find(c.key);if(it!=cache.end()&&nowms()<it->second.expiry){touch(it);response(c,200,it->second.body->size(),it->second.extra,it->second.body);return;}c.upout=(c.head?"HEAD ":"GET ")+c.target.substr(8)+" HTTP/1.1\r\nHost: "+c.host+"\r\n";if(!c.lang.empty())c.upout+="Accept-Language: "+c.lang+"\r\n";if(!c.head&&it!=cache.end()&&!it->second.etag.empty())c.upout+="If-None-Match: "+it->second.etag+"\r\n";c.upout+="Connection: close\r\n\r\n";c.upos=0;c.upin.clear();int u=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(u<0){error(c,502);return;}c.up=u;int r=connect(u,(sockaddr*)&origin,sizeof(origin));if(r<0&&errno!=EINPROGRESS){error(c,502);return;}upstream[u]=c.fd;c.state=2;c.deadline=nowms()+cfg.wtime;ev(c.fd,0);ev(u,EPOLLOUT,EPOLL_CTL_ADD);}
 void request(Client&c,string h){c.requests++;c.head=false;c.gateway=false;c.close=c.requests>=cfg.maxreq;c.host.clear();c.lang.clear();c.target.clear();c.key.clear();size_t e=h.find("\r\n");if(e==string::npos){error(c,400,true);return;}string line=h.substr(0,e);size_t a=line.find(' '),b=a==string::npos?string::npos:line.find(' ',a+1);if(a==string::npos||b==string::npos||line.find(' ',b+1)!=string::npos){error(c,400,true);return;}string method=line.substr(0,a),target=line.substr(a+1,b-a-1),ver=line.substr(b+1);if(!istoken(method)||(ver!="HTTP/1.1"&&ver!="HTTP/1.0")){error(c,400,true);return;}vector<pair<string,string>> f;if(!parsefields(h.substr(e+2),f)){error(c,400,true);return;}int hosts=0,cls=0;bool te=false,clbad=false,connclose=false;string lang;for(auto &kv:f){auto &k=kv.first;auto &v=kv.second;if(k=="host"){hosts++;c.host=v;}else if(k=="content-length"){cls++;unsigned long long x;if(!number(v,x)||x!=0)clbad=true;}else if(k=="transfer-encoding")te=true;else if(k=="connection"&&hasToken(v,"close"))connclose=true;else if(k=="accept-language"){if(!lang.empty())lang+=", ";lang+=v;}}c.lang=lang;if(ver=="HTTP/1.0"||connclose)c.close=true;string path;int pe=pathdecode(target,path);if(pe){error(c,pe,pe==400);return;}c.gateway=path.rfind("/gateway/",0)==0;if(c.gateway&&(hosts!=1||c.host.empty())){error(c,400,true);return;}if(te||cls>1||clbad){error(c,400,true);return;}if(method!="GET"&&method!="HEAD"){error(c,405);return;}c.head=method=="HEAD";c.target=target;if(c.gateway){ // Gateway selection uses the literal prefix, never a decoded alias
 if(target.rfind("/gateway/",0)!=0){error(c,404);return;}c.key=to_string(c.host.size())+":"+c.host+to_string(target.size())+":"+target+to_string(lang.size())+":"+lang;gateway(c);}else local(c,path);}
 void consume(Client&c){if(c.state!=0)return;size_t end=c.in.find("\r\n\r\n");size_t check=end==string::npos?c.in.size():end+4;for(size_t i=0;i<check;i++){char x=c.in[i];if(x==0||(x=='\n'&&(i==0||c.in[i-1]!='\r'))||(x=='\r'&&i+1<check&&c.in[i+1]!='\n')){c.requests++;c.head=false;error(c,400,true);return;}}if(end==string::npos){if((long long)c.in.size()>cfg.hbytes){c.requests++;c.head=false;error(c,431,true);}return;}if(end+4>(unsigned long long)cfg.hbytes){c.requests++;c.head=false;error(c,431,true);return;}string h=c.in.substr(0,end+4);c.in.erase(0,end+4);c.first=c.in.empty()?0:nowms();request(c,move(h));}
 void readclient(Client&c){char buf[8192];for(;;){size_t lim=(size_t)min<long long>(cfg.hbytes,1048576);if(lim==0)lim=1;size_t nmax=min(sizeof(buf),lim+1);ssize_t n=recv(c.fd,buf,nmax,0);if(n>0){if(c.in.empty())c.first=nowms();c.in.append(buf,n);consume(c);if(c.state!=0)return;continue;}if(n==0){drop(c.fd);return;}if(errno==EINTR)continue;if(errno!=EAGAIN&&errno!=EWOULDBLOCK)drop(c.fd);return;}}
 void writeclient(Client&c){while(c.opos<c.out.size()){ssize_t n=send(c.fd,c.out.data()+c.opos,c.out.size()-c.opos,MSG_NOSIGNAL);if(n>0){c.opos+=n;c.deadline=nowms()+cfg.wtime;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;drop(c.fd);return;}if(!c.head){if(c.body){while(c.bpos<c.body->size()){ssize_t n=send(c.fd,c.body->data()+c.bpos,c.body->size()-c.bpos,MSG_NOSIGNAL);if(n>0){c.bpos+=n;c.deadline=nowms()+cfg.wtime;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;drop(c.fd);return;}}else if(c.file>=0){while(c.fpos<c.flen){ssize_t n=sendfile(c.fd,c.file,&c.fpos,min<off_t>(c.flen-c.fpos,1<<20));if(n>0){c.deadline=nowms()+cfg.wtime;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;drop(c.fd);return;}}}if(c.file>=0){close(c.file);c.file=-1;}c.body.reset();if(c.close){drop(c.fd);return;}c.out.clear();c.state=0;c.deadline=nowms()+cfg.idle;ev(c.fd,EPOLLIN);if(!c.in.empty())consume(c);}
 void upsend(Client&c){int err=0;socklen_t l=sizeof(err);if(getsockopt(c.up,SOL_SOCKET,SO_ERROR,&err,&l)||err){error(c,502);return;}while(c.upos<c.upout.size()){ssize_t n=send(c.up,c.upout.data()+c.upos,c.upout.size()-c.upos,MSG_NOSIGNAL);if(n>0){c.upos+=n;c.deadline=nowms()+cfg.wtime;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;error(c,502);return;}c.state=3;ev(c.up,EPOLLIN);}
 // Returns 0 incomplete, 1 completed, -1 invalid.
 int parseup(Client&c){size_t e=c.upin.find("\r\n\r\n");if(e==string::npos)return c.upin.size()>65536?-1:0;if(e>65536)return -1;size_t line=c.upin.find("\r\n");if(line==string::npos||line>e)return -1;string first=c.upin.substr(0,line);if(first.size()<12||first.compare(0,7,"HTTP/1.")||first[8]!=' '||!isdigit((unsigned char)first[9])||!isdigit((unsigned char)first[10])||!isdigit((unsigned char)first[11]))return -1;int status=(first[9]-'0')*100+(first[10]-'0')*10+first[11]-'0';vector<pair<string,string>> f;if(!parsefields(c.upin.substr(line+2,e+4-(line+2)),f))return -1;long long len=-1;bool bad=false,privatecache=false,varybad=false,setcookie=false;string etag,extra;long long ttl=cfg.ttl;for(auto &kv:f){string k=kv.first,v=kv.second;if(k=="content-length"){unsigned long long x;if(len!=-1||!number(v,x)||x>LLONG_MAX)bad=true;else len=x;}else if(k=="transfer-encoding")bad=true;else if(k=="cache-control"){string low=lower(v);size_t p=0;while(p<=low.size()){size_t z=low.find(',',p);if(z==string::npos)z=low.size();string d=trim(low.substr(p,z-p));size_t eq=d.find('=');string name=trim(d.substr(0,eq));if(name=="private"||name=="no-store"||name=="no-cache")privatecache=true;if(name=="max-age"||name=="s-maxage"){unsigned long long x;string value=eq==string::npos?"":trim(d.substr(eq+1));if(value.size()>=2&&value.front()=='"'&&value.back()=='"')value=value.substr(1,value.size()-2);if(!number(value,x))privatecache=true;else ttl=min<long long>(ttl,x>(unsigned long long)LLONG_MAX/1000?LLONG_MAX:(long long)x*1000);}if(z==low.size())break;p=z+1;}}else if(k=="set-cookie")setcookie=true;else if(k=="etag")etag=v;else if(k=="vary"){size_t p=0;while(p<=v.size()){size_t z=v.find(',',p);if(z==string::npos)z=v.size();string t=lower(trim(v.substr(p,z-p)));if(t!="accept-language")varybad=true;if(z==v.size())break;p=z+1;}}if(k!="content-length"&&k!="connection"&&k!="transfer-encoding"&&k!="keep-alive"&&k!="proxy-connection"&&k!="upgrade"&&k!="trailer")extra+=k+": "+v+"\r\n";}
 if(bad)return -1;if(status==304){auto it=cache.find(c.key);if(it==cache.end()||c.head)return -1;auto body=it->second.body;string ex=it->second.extra;if(privatecache||varybad||setcookie||ttl<=0){erasecache(it);}else{it->second.expiry=nowms()+ttl;it->second.ttl=ttl;touch(it);}response(c,200,body->size(),ex,body);return 1;}if(len<0)return -1;if(c.head){response(c,status,len,extra);return 1;}if((unsigned long long)len>256ULL*1024*1024)return -1;if(c.upin.size()-e-4<(unsigned long long)len)return 0;auto body=make_shared<string>(c.upin.data()+e+4,(size_t)len);if(status==200&&!privatecache&&!varybad&&!setcookie&&ttl>0)store(c.key,body,extra,etag,ttl);else if(status==200){auto it=cache.find(c.key);if(it!=cache.end())erasecache(it);}response(c,status,len,extra,body);return 1;}
 void upread(Client&c){char b[16384];for(;;){ssize_t n=recv(c.up,b,sizeof(b),0);if(n>0){c.deadline=nowms()+cfg.wtime;c.upin.append(b,n);int r=parseup(c);if(r<0){error(c,502);return;}if(r>0)return;continue;}if(n==0){error(c,502);return;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)return;error(c,502);return;}}
 public:Server(Config x):cfg(move(x)){}int run(){signal(SIGPIPE,SIG_IGN);if(!address(cfg.origin,origin))return 1;root=open(cfg.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(root<0)return 1;sockaddr_in bindaddr;if(!address(cfg.listen,bindaddr))return 1;ls=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(ls<0)return 1;int one=1;setsockopt(ls,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));if(bind(ls,(sockaddr*)&bindaddr,sizeof(bindaddr))||listen(ls,1024))return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;ev(ls,EPOLLIN,EPOLL_CTL_ADD);epoll_event events[512];for(;;){int n=epoll_wait(ep,events,512,100);long long now=nowms();if(n<0&&errno!=EINTR)return 1;for(int i=0;i<n;i++){int fd=events[i].data.fd;if(fd==ls){for(;;){int s=accept4(ls,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(s<0){if(errno==EINTR)continue;break;}if((long long)clients.size()>=cfg.maxconn){close(s);continue;}auto c=make_unique<Client>();c->fd=s;c->deadline=nowms()+cfg.idle;clients.emplace(s,move(c));ev(s,EPOLLIN,EPOLL_CTL_ADD);}continue;}auto ui=upstream.find(fd);if(ui!=upstream.end()){auto ci=clients.find(ui->second);if(ci==clients.end())continue;Client &c=*ci->second;if(c.state==2)upsend(c);else if(c.state==3)upread(c);continue;}auto it=clients.find(fd);if(it==clients.end())continue;Client&c=*it->second;if(c.state==0)readclient(c);else if(c.state==1)writeclient(c);else if(events[i].events&(EPOLLHUP|EPOLLERR|EPOLLRDHUP))drop(fd);}vector<int> expired;for(auto &kv:clients){Client&c=*kv.second;if(c.state==0){if(c.first&&now-c.first>=cfg.htime)expired.push_back(kv.first);else if(!c.first&&now>=c.deadline)expired.push_back(kv.first);}else if(now>=c.deadline)expired.push_back(kv.first);}for(int fd:expired){auto it=clients.find(fd);if(it==clients.end())continue;Client&c=*it->second;if(c.state==2||c.state==3)error(c,502);else drop(fd);}}}};
int main(int argc,char**argv){if(argc!=3||string(argv[1])!="--config")return 1;Config c;if(!config(argv[2],c))return 1;return Server(move(c)).run();}
